const buildBacktestPrompt = createStep({
  id: "build-backtest-analysis-prompt",
  inputSchema: object({
    summary: string()
  }),
  outputSchema: object({
    prompt: string()
  }),
  execute: async ({ inputData }) => {
    return {
      prompt: [
        "Analyze the following FreqDash Strategy Lab run.",
        "Respond in Russian.",
        "Keep the answer concise and practical.",
        "Use four labeled paragraphs: \u0418\u0442\u043E\u0433, \u0421\u0438\u043B\u044C\u043D\u044B\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B, \u0420\u0438\u0441\u043A\u0438, \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0448\u0430\u0433.",
        "Do not invent missing metrics.",
        "",
        inputData.summary
      ].join("\n")
    };
  }
});
const analyzeBacktest = createStep({
  id: "analyze-backtest-run",
  inputSchema: object({
    prompt: string()
  }),
  outputSchema: object({
    analysis: string()
  }),
  execute: async ({ inputData }) => {
    const response = await tradingAgent.generate(inputData.prompt);
    return {
      analysis: response.text
    };
  }
});
const backtestAnalysisWorkflow = createWorkflow2({
  id: "backtest-analysis-workflow",
  inputSchema: object({
    summary: string()
  }),
  outputSchema: object({
    analysis: string()
  })
}).then(buildBacktestPrompt).then(analyzeBacktest).commit();

